class Solution:
    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:
        # Ensure nums1 is the smaller array
        if len(nums1) > len(nums2):
            nums1, nums2 = nums2, nums1

        m, n = len(nums1), len(nums2)
        total = m + n
        half = (total + 1) // 2

        left, right = 0, m
        while left <= right:
            i = (left + right) // 2
            j = half - i

            # Get the left and right elements around the partition
            nums1_left = nums1[i - 1] if i > 0 else float('-inf')
            nums1_right = nums1[i] if i < m else float('inf')
            nums2_left = nums2[j - 1] if j > 0 else float('-inf')
            nums2_right = nums2[j] if j < n else float('inf')

            # Check if partition is correct
            if nums1_left <= nums2_right and nums2_left <= nums1_right:
                # Found correct partition
                if total % 2 == 1:
                    return max(nums1_left, nums2_left)
                else:
                    return (max(nums1_left, nums2_left) + min(nums1_right, nums2_right)) / 2
            elif nums1_left > nums2_right:
                # Move left in nums1
                right = i - 1
            else:
                # Move right in nums1
                left = i + 1

        # Should never reach here
        raise ValueError("Input arrays are not sorted")

class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        m, n = len(s), len(p)

        # Use a single 1D array to minimize memory usage
        dp = [False] * (n + 1)
        dp[0] = True

        # Handle patterns like a*, a*b*, etc. that can match empty string
        for j in range(2, n + 1):
            if p[j - 1] == '*':
                dp[j] = dp[j - 2]

        # Process each character of s
        for i in range(1, m + 1):
            # Save the diagonal value (dp[j-1] from previous row) before overwriting
            diag = dp[0]
            dp[0] = False  # Empty pattern can't match non-empty string

            for j in range(1, n + 1):
                # Save current dp[j] before overwriting (it's prev[j] for next iteration)
                temp = dp[j]

                if p[j - 1] == '*':
                    # Zero occurrences of preceding char
                    dp[j] = dp[j - 2]
                    # One or more occurrences if current char matches
                    if p[j - 2] == '.' or p[j - 2] == s[i - 1]:
                        dp[j] = dp[j] or temp  # temp is prev[j]
                else:
                    if p[j - 1] == '.' or p[j - 1] == s[i - 1]:
                        dp[j] = diag  # diag is prev[j-1]
                    else:
                        dp[j] = False

                # Update diag to be prev[j] for the next iteration
                diag = temp

        return dp[n]

