class Solution:
    def merge(self, intervals: List[List[int]]) -> List[List[int]]:
        if not intervals:
            return []

        # Sort intervals by start time (in-place to avoid extra memory)
        intervals.sort()

        merged = [intervals[0]]

        for start, end in intervals[1:]:
            # If current interval overlaps with the last merged interval
            if start <= merged[-1][1]:
                # Merge by updating the end if needed
                if end > merged[-1][1]:
                    merged[-1][1] = end
            else:
                # No overlap, add as new interval
                merged.append([start, end])

        return merged

class Solution:
    def uniquePaths(self, m: int, n: int) -> int:
        # Use math.comb for O(1) space and O(min(m,n)) time
        # Total paths = C(m+n-2, m-1) = C(m+n-2, n-1)
        # Choose the smaller dimension to minimize computation
        from math import comb
        return comb(m + n - 2, min(m - 1, n - 1))
